{
  "vulnerable_symbols": [
    "yaml.full_load",
    "yaml.load"
  ],
  "trigger": "应用使用 PyYAML 5.3 的 yaml.full_load 或 yaml.load(..., Loader=yaml.FullLoader) 解析攻击者可控 YAML，且 YAML 含 !!python/object/new 等危险标签。",
  "exploit_evidence": [
    {
      "src": 0,
      "kind": "poc",
      "quote": "RCE in PyYAML before 5.4 via !!python/object/new tags with FullLoader."
    },
    {
      "src": 1,
      "kind": "poc",
      "quote": "EIP currently links 5 repository PoCs, 6 curated repository PoCs, and 2 lab environments to CVE-2020-14343."
    },
    {
      "src": 2,
      "kind": "poc",
      "quote": "PyYAML 在使用 yaml.load() 解析不可信数据时,未限制危险的 YAML 标签(如 !!python/object),攻击者可构造恶意 YAML 内容执行任意 Python 代码。"
    }
  ],
  "fixed_version": "5.4",
  "summary_zh": "PyYAML 5.3 FullLoader 解析不可信 YAML 可 RCE，升级 5.4 或 safe_load。"
}
